	std::span<const Descriptor> All() noexcept
	{
		return kDescriptors;
	}

	std::span<const Page> Pages() noexcept
	{
		return kPages;
	}

	std::span<const Category> Categories() noexcept
	{
		return kCategories;
	}

	const Descriptor* Find(std::string_view a_id) noexcept
	{
		for (const auto& descriptor : kDescriptors) {
			if (descriptor.id == a_id) {
				return std::addressof(descriptor);
			}
		}
		return nullptr;
	}
